#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's quoting undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"; fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line). Idempotent. Creates ENV_FILE at mode 0600; writes through a symlink
# and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# The real-hardware checks for PR #43: the Hub on its own machine, a real
# Samsung TV, and the Player. Run it on the machine that will run the Hub,
# from the root of a checkout of the PR's branch. Every answer lands in
# $ENV_FILE, which you paste back into the Claude session; nothing secret is
# asked for, and the file is never committed.

ENV_FILE="${ENV_FILE:-$HOME/media-centre-hardware-results.env}"
TOTAL_STAGES=13
HUB_PORT="${HUB_PORT:-41080}"

# check KEY "What to check" records pass, fail or skip, with a note.
check() {
  local key="$1" question="$2" verdict="" note=""
  step "$question"
  while [[ ! "$verdict" =~ ^(pass|fail|skip)$ ]]; do
    printf '  %s  pass / fail / skip:%s ' "$BOLD" "$RESET"
    read -r verdict || verdict=skip
  done
  printf '  %s  Note (what you saw; Enter for none):%s ' "$DIM" "$RESET"
  read -r note || true
  write_env "$key" "$verdict${note:+: $note}"
}

# record KEY "label" COMMAND… runs a read-only command and saves its output.
record() {
  local key="$1" label="$2" out; shift 2
  out=$("$@" 2>&1 | tr '\n' ' ' | sed 's/  */ /g' | cut -c1-600) || true
  say "$label: $out"
  write_env "$key" "$out"
}

banner "media-centre: real-hardware checks for PR #43"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "The Hub's machine (PRD §11.2, #28)"
say "This records what this machine is, which decides the hardware encoder."
record HUB_CPU "CPU" sh -c "lscpu | grep 'Model name' | sed 's/Model name:\s*//'"
record HUB_GPU "GPU" sh -c "lspci 2>/dev/null | grep -iE 'vga|3d|display' || echo 'lspci not available'"
record HUB_DRI "GPU devices" sh -c "ls /dev/dri 2>/dev/null || echo none"
record HUB_OS "OS" sh -c ". /etc/os-release && echo \"\$PRETTY_NAME\""
ask HUB_MACHINE "Make and model of this machine (e.g. Beelink SER5, Intel NUC 12):"
write_env HUB_MACHINE "$HUB_MACHINE"
pause

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Start the Hub from this branch"
say "Builds the Hub's image here and runs it with host networking and a volume."
say "The folder below is mounted read-only as /media in the Hub, for Media Sources."
ask MEDIA_DIR "Folder holding films and music to test with (absolute path):"
write_env MEDIA_DIR "$MEDIA_DIR"
GPU_FLAGS=()
[[ -d /dev/dri ]] && GPU_FLAGS=(--device /dev/dri)
if command -v nvidia-smi >/dev/null 2>&1; then GPU_FLAGS+=(--gpus all); fi
say "GPU passed in: ${GPU_FLAGS[*]:-none}"
if confirm "Build the image and (re)create the container 'media-centre-hub'?"; then
  docker build -t media-centre-hub .
  docker rm -f media-centre-hub >/dev/null 2>&1 || true
  docker run -d --name media-centre-hub --network host -e "HUB_PORT=$HUB_PORT" \
    "${GPU_FLAGS[@]}" -v media-centre-data:/data -v "$MEDIA_DIR:/media:ro" \
    --restart unless-stopped media-centre-hub >/dev/null
  sleep 5
fi
record HUB_LOG "Hub log" docker logs --tail 5 media-centre-hub
HUB_IP=$(hostname -I 2>/dev/null | awk '{print $1}')
write_env HUB_IP "$HUB_IP"
say "Open http://$HUB_IP:$HUB_PORT on your phone, on the home Wi-Fi."
check CHECK_REMOTE_LOADS "The Remote loads on the phone and Settings says it is connected to the Hub"

# ── 3 ────────────────────────────────────────────────────────────────────
stage "The TV"
step "On the TV: Settings → Support → About This TV."
ask TV_MODEL "TV model code (e.g. QE55Q80TATXXU):"
write_env TV_MODEL "$TV_MODEL"
ask TV_FIRMWARE "Software version (e.g. T-NKMDEUC-2400.1):"
write_env TV_FIRMWARE "$TV_FIRMWARE"
step "On the TV: Settings → General → Network → Network Status → IP Settings."
ask TV_IP "TV IP address:"
write_env TV_IP "$TV_IP"
ask TV_IS_FRAME "Is it a Frame TV? (yes/no):"
write_env TV_IS_FRAME "$TV_IS_FRAME"
pause

# ── 4 ────────────────────────────────────────────────────────────────────
stage "#18: what the TV's own API reports"
say "Read-only requests to the TV, on port 8001. Switch the TV on first."
record TV_DEVICE_INFO "Device info" sh -c "curl -s --max-time 5 http://$TV_IP:8001/api/v2/ | tr -d '\n'"
record SPIKE_DEVELOPER_FIELDS "developerMode / developerIP" sh -c \
  "curl -s --max-time 5 http://$TV_IP:8001/api/v2/ | grep -oE '\"developer(Mode|IP)\":\"[^\"]*\"' | tr '\n' ' ' || echo 'not reported'"
step "Open YouTube on the TV, so it is in front."
pause
record SPIKE_YOUTUBE_IN_FRONT "YouTube app status, in front" curl -s --max-time 5 "http://$TV_IP:8001/api/v2/applications/111299001912"
step "Now press Home and go back to live TV, leaving YouTube running behind."
pause
record SPIKE_YOUTUBE_BEHIND "YouTube app status, behind live TV" curl -s --max-time 5 "http://$TV_IP:8001/api/v2/applications/111299001912"
note "The two answers should differ in \"visible\" for Now Showing to be reliable."
pause

# ── 5 ────────────────────────────────────────────────────────────────────
stage "#19: finding, adding and pairing"
say "In the Remote: Settings → TVs."
check CHECK_SSDP "Find TVs finds this TV"
check CHECK_ADD_BY_IP "Adding it by IP address works (remove and re-add it to try)"
check CHECK_PAIRING_PROMPT "The pairing prompt appears on the TV, and allowing it pairs the TV"
check CHECK_NAMES_ROOMS "A name and a Room can be given, and the TV list shows 'Room · Name' (two TVs if you have them)"
step "Restart the Hub now: docker restart media-centre-hub (in another terminal)."
check CHECK_TOKEN_PERSISTS "After the restart, the TV is still paired (keys still work)"
step "On the TV: Settings → General → External Device Manager → Device Connection Manager → Device List: delete the Hub."
check CHECK_PAIR_AGAIN "The Remote then offers 'Pair again', and pairing again works"

# ── 6 ────────────────────────────────────────────────────────────────────
stage "#19: power and volume"
check CHECK_WOL "With the TV in standby, the Power button wakes it (Wake-on-LAN)"
check CHECK_POWER_OFF "The Power button switches it off (on a Frame, fully off, not Art Mode)"
check CHECK_VOLUME_READ "The volume slider shows the TV's real volume"
check CHECK_VOLUME_SET "Moving the slider and Mute change the TV's volume"
check CHECK_VOLUME_STANDBY "In standby, the volume slider is disabled"

# ── 7 ────────────────────────────────────────────────────────────────────
stage "#19: text, TV Menu mode, Now Showing and the Developer section"
step "Open YouTube's search on the TV."
check CHECK_TEXT "Typing in the Remote's text field reaches the TV's on-screen keyboard"
step "Open TV Menu mode and try each shortcut."
check CHECK_SHORTCUTS "Each TV Menu shortcut does what it says; list any the TV ignores, and whether the Remote reported them"
check CHECK_NOW_SHOWING "Now Showing names the app in front for Live TV, YouTube and Netflix"
check CHECK_DEVELOPER_SECTION "The Developer section shows the device info, and Developer Mode and IP (or says the TV doesn't report them)"

# ── 8 ────────────────────────────────────────────────────────────────────
stage "#34: Developer Mode on the TV"
say "Follow the Developer section's steps on the TV, with the Hub's IP: $HUB_IP"
step "Apps → type 1 2 3 4 5 with the remote → Developer mode On → enter $HUB_IP → restart the TV (hold Power)."
pause
record SPIKE_DEVELOPER_AFTER "developerMode / developerIP after switching on" sh -c \
  "curl -s --max-time 5 http://$TV_IP:8001/api/v2/ | grep -oE '\"developer(Mode|IP)\":\"[^\"]*\"' | tr '\n' ' ' || echo 'not reported'"
check CHECK_INSTALL_BUTTON "The Developer section now shows Install / update Player"
record SPIKE_SDB_SHELL "What sdb shell allows on this retail TV" sh -c \
  "docker exec media-centre-hub sh -c 'sdb connect $TV_IP:26101 >/dev/null; sdb shell id; sdb shell ls /opt/usr/apps | head -3; sdb disconnect >/dev/null' 2>&1"

# ── 9 ────────────────────────────────────────────────────────────────────
stage "#34: install, launch and uninstall the Player"
say "Settings needs your Samsung signing certificate (author and distributor .p12)."
note "See docs/processes/installing-the-player-with-tizen-studio.md for making one."
note "Its passwords go into the Remote only, never into this wizard."
check CHECK_CERTIFICATE "The certificate and passwords are accepted in Settings"
check CHECK_INSTALL "Install / update Player installs it, with progress shown"
check CHECK_LAUNCH "Launch Player opens it on the TV, connected to the Hub"
check CHECK_REOPEN "Opened from the TV's own app list, it shows 'Waiting for the Remote' with the Hub's address, and reconnects"
check CHECK_UNINSTALL "Uninstall Player removes it (then install it again for the next stages)"

# ── 10 ───────────────────────────────────────────────────────────────────
stage "#35: one Media File per Route"
say "Settings → Media Sources: add /media. Then play each from Watch & Listen."
note "Use your own files; Watch & Listen shows each one's Route."
check CHECK_DIRECT_MP4 "A plain MP4 (H.264/AAC) plays by Direct Play"
check CHECK_REMUX_MKV "An MKV the TV decodes but needs remuxing plays (Remux)"
check CHECK_DTS_MKV "An MKV with DTS audio plays (Audio Conversion)"
check CHECK_XVID_AVI "A DivX/Xvid AVI plays (Full Conversion)"
check CHECK_HEVC_HDR "A 4K HEVC HDR file plays by Direct Play, in HDR"
check CHECK_NOW_SHOWING_PLAYER "Now Showing names the Player and the Media File while it plays"

# ── 11 ───────────────────────────────────────────────────────────────────
stage "#35: seeking, subtitles, music"
check CHECK_SEEK_DIRECT "Seeking works on Direct Play"
check CHECK_SEEK_HLS "Seeking works on a converted Route (HLS), including far ahead"
check CHECK_PREVIEW "Now Showing's preview picture follows the position, and holds still when paused"
check CHECK_MEDIA_KEYS "The physical remote's play/pause, rewind, fast-forward and Back control the Player"
check CHECK_RESUME "Stopping halfway and choosing the file again offers 'Resume from …', and it resumes there"
check CHECK_SUBS_SIDECAR "A sidecar subtitle (e.g. Film.en.srt beside Film.mkv) displays"
check CHECK_SUBS_EMBEDDED "An embedded text subtitle displays"
check CHECK_SUBS_IMAGE "An image subtitle (PGS or VobSub) displays, burned in after the warning"
check CHECK_AUDIO_TRACK "Switching audio track keeps playing near the same position"
check CHECK_FLAC_QUEUE "Play folder on a FLAC album plays as a Queue with cover art; next, previous, shuffle and repeat work"

# ── 12 ───────────────────────────────────────────────────────────────────
stage "#28: does Full Conversion keep up in real time?"
say "Encodes 30 s of 1080p and 4K test picture in the Hub's container, as Full Conversion does."
record FULL_CONVERSION_ENCODER "Encoder the Hub chose" sh -c \
  "docker logs media-centre-hub 2>&1 | grep -i 'Full Conversion' | tail -3 || echo 'no message (it uses the first that works)'"
speed() { # speed SIZE ENCODER_ARGS… prints ffmpeg's final speed=
  local size="$1"; shift
  docker exec media-centre-hub ffmpeg -hide_banner -nostdin -y "$@" 2>&1 | tr '\r' '\n' | grep -oE 'speed= *[0-9.]+x' | tail -1 || echo "failed ($size)"
}
SRC1080=(-f lavfi -i testsrc2=size=1920x1080:rate=24:duration=30)
SRC4K=(-f lavfi -i testsrc2=size=3840x2160:rate=24:duration=30)
SW=(-c:v libx264 -preset veryfast -crf 21 -pix_fmt yuv420p -f null -)
write_env SPEED_SOFTWARE_1080P "$(speed 1080p "${SRC1080[@]}" "${SW[@]}")"
write_env SPEED_SOFTWARE_4K "$(speed 4k "${SRC4K[@]}" "${SW[@]}")"
if [[ -e /dev/dri/renderD128 ]]; then
  VA=(-vf format=nv12,hwupload -c:v h264_vaapi -qp 21 -f null -)
  write_env SPEED_VAAPI_1080P "$(speed 1080p -vaapi_device /dev/dri/renderD128 "${SRC1080[@]}" "${VA[@]}")"
  write_env SPEED_VAAPI_4K "$(speed 4k -vaapi_device /dev/dri/renderD128 "${SRC4K[@]}" "${VA[@]}")"
fi
if command -v nvidia-smi >/dev/null 2>&1; then
  NV=(-pix_fmt yuv420p -c:v h264_nvenc -preset p4 -rc constqp -qp 21 -f null -)
  write_env SPEED_NVENC_1080P "$(speed 1080p "${SRC1080[@]}" "${NV[@]}")"
  write_env SPEED_NVENC_4K "$(speed 4k "${SRC4K[@]}" "${NV[@]}")"
fi
note "1.0x or more keeps up in real time."
check CHECK_XVID_HW "The Xvid AVI from stage 10 plays smoothly again, now with the GPU passed in"
check CHECK_FULL_CONVERSION_4K "A 4K file needing Full Conversion plays without stalling (skip if you have none)"

# ── 13 ───────────────────────────────────────────────────────────────────
stage "Send the results back"
say "Everything is in $ENV_FILE. It holds no passwords or tokens."
say "Paste its contents into the Claude session, which records them on #18, #19, #28, #34 and #35."
pause "Press Enter to finish."

finish
say "Results: $ENV_FILE"
